// Runtime interface translation (audit OV-074). Landing prose is translated at build time; this covers the app
// itself: toolbar, panels, dialogs and messages. Strings are keyed by their English text, so a missing translation
// falls back to English instead of showing a key. Machine-quality wording: needs a native-speaker review.

export type Lang = 'en' | 'es' | 'de' | 'fr' | 'pt';

function detect(): Lang {
  try {
    const cfg = JSON.parse(document.getElementById('page-config')?.textContent || '{}');
    if (cfg.lang && ['es', 'de', 'fr', 'pt'].includes(cfg.lang)) return cfg.lang;
  } catch { /* default */ }
  const l = (document.documentElement.lang || 'en').slice(0, 2) as Lang;
  return ['es', 'de', 'fr', 'pt'].includes(l) ? l : 'en';
}
export const LANG: Lang = typeof document !== 'undefined' ? detect() : 'en';

