const DICT: Record<Exclude<Lang, 'en'>, Map<string, string>> = { es: new Map(), de: new Map(), fr: new Map(), pt: new Map() };
for (const [en, es, de, fr, pt] of ROWS) { DICT.es.set(en, es); DICT.de.set(en, de); DICT.fr.set(en, fr); DICT.pt.set(en, pt); }

/** Translates an English interface string; `{name}` placeholders are filled from vars. */
export function t(en: string, vars?: Record<string, string | number>): string {
  let s = LANG === 'en' ? en : DICT[LANG].get(en) ?? en;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}

/** Translates elements marked with data-i18n (text) and data-i18n-tip / data-i18n-label (attributes). */
export function applyStaticI18n(root: ParentNode = document) {
  root.querySelectorAll<HTMLElement>('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n || el.textContent || ''); });
  // Accessible names too: screen readers announce aria-label, not the visible text (audit F11).
  if (LANG !== 'en') root.querySelectorAll<HTMLElement>('[aria-label]').forEach((el) => {
    const base = el.dataset.labelEn ?? el.getAttribute('aria-label')!;
    el.dataset.labelEn = base;
    el.setAttribute('aria-label', t(base));
  });
  root.querySelectorAll<HTMLElement>('[data-tip]').forEach((el) => {
    const base = el.dataset.tipEn ?? el.dataset.tip!;
    el.dataset.tipEn = base;
    const m = base.match(/^(.*?)(\s*\([^)]*\))?$/);
    el.dataset.tip = t(m?.[1] ?? base) + (m?.[2] ?? '');
  });
}

/** Path prefix for the current language ('' for English, 'es/' …), for links that must stay in the language (OV-075). */
export const LANG_PREFIX = LANG === 'en' ? '' : LANG + '/';
